import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import './../assets/css/login.css';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faEye, faEyeSlash } from '@fortawesome/free-solid-svg-icons';
import { faTwitter, faFacebookF, faGooglePlusG } from '@fortawesome/free-brands-svg-icons';

const Login = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const { email, password } = formData;
  const navigate = useNavigate();

  const onChange = e => setFormData({ ...formData, [e.target.name]: e.target.value });

  const onSubmit = async e => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', formData);
      localStorage.setItem('token', res.data.token);
      localStorage.setItem('role', res.data.role);

      if (res.data.role === 'admin') {
        navigate('/admin-dashboard');
      } else if (res.data.role === 'teacher') {
        navigate('/teacher-dashboard');
      }
    } catch (err) {
      if (err.response) {
        alert(err.response.data.msg);
      } else {
        alert('Network Error. Please try again.');
      }
    }
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };

  return (
    <div className="login-page">
      {/* Left Column: Branding and Text */}
      <div className="branding-column">
        <div className="branding-content">
          <div className="logo">
            <h1 className="logo-text">SKIT</h1>
          </div>
          <h2 className="welcome-message">Welcome to SKIT Community</h2>
          <p className="tagline">WE STRIVE FOR EXCELLENCE</p>

          <div className="branding-footer">
            <p className="contact-info">For any queries, contact <a href="mailto:erp@skit.ac.in">erp@skit.ac.in</a></p>
            <div className="social-icons">
              <a href="#" className="social-icon"><FontAwesomeIcon icon={faTwitter} /></a>
              <a href="#" className="social-icon"><FontAwesomeIcon icon={faFacebookF} /></a>
              <a href="#" className="social-icon"><FontAwesomeIcon icon={faGooglePlusG} /></a>
            </div>
          </div>
        </div>
      </div>

      {/* Right Column: Login Form */}
      <div className="form-column">
        <div className="login-form-container">
          <h2 className="form-title">Sign in to your account</h2>
          <form onSubmit={onSubmit}>
            <div className="input-group">
              <input 
                type="text" 
                name="email" 
                value={email} 
                onChange={onChange} 
                placeholder="Username" 
                required 
              />
            </div>

            <div className="input-group password-group">
              <input 
                type={showPassword ? "text" : "password"} 
                name="password" 
                value={password} 
                onChange={onChange} 
                placeholder="Password" 
                required 
              />
              <FontAwesomeIcon 
                icon={showPassword ? faEyeSlash : faEye} 
                className="password-toggle" 
                onClick={togglePasswordVisibility} 
              />
            </div>

            <div className="form-options">
              <div className="remember-me">
                <input type="checkbox" id="rememberMe" />
                <label htmlFor="rememberMe">Remember me</label>
              </div>
              <a href="#" className="forgot-password">Forgot Password?</a>
            </div>

            <div className="recaptcha-group">
              <div className="recaptcha-box"></div>
              <span>I'm not a robot</span>
            </div>

            <button type="submit" className="sign-in-btn">Sign in</button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;
